TOPICS = build_guided_catalog([
    ("sonar-intro", "What SonarQube Is and Why Teams Use It", "analysis", "basic", "SonarQube continuously inspects source code for maintainability, reliability and security issues. It reports findings and measures quality; it does not replace tests, code review or threat modeling.", "Code → scanner → analysis report → quality gate", "What does SonarQube add to a review process?", "A consistent, automated view of code issues and trends so teams can review risks early and apply shared policy."),
    ("sonar-project", "Projects, Branches and Pull Requests", "analysis", "basic", "A project identifies the codebase and its analysis history. Branch and pull-request analysis relate findings to the change under review.", "sonar.projectKey=payments-api", "Why analyze a pull request?", "It lets reviewers see new issues and gate the change before merging, using the project's configured analysis policy."),
    ("sonar-scanner", "Scanner and Build Integration", "analysis", "basic", "The scanner collects source and analysis context, invokes language analyzers and submits a report to the SonarQube server. Build integration can provide compiled information for some languages.", "sonar-scanner -Dsonar.projectKey=payments-api", "Does the scanner itself decide the quality gate?", "No. It submits analysis; the server processes results and evaluates the configured gate."),
    ("sonar-sources-tests", "Sources, Tests and Exclusions", "analysis", "intermediate", "Correctly separate production sources from test code and configure exclusions narrowly. Broad exclusions can hide code from analysis and weaken the signal.", "sonar.sources=src; sonar.tests=tests", "Why avoid broad exclusions?", "They can silently remove important code from analysis, coverage and issue reporting."),
    ("sonar-quality-profile", "Quality Profiles", "rules", "basic", "A quality profile is a language-specific set of active rules and parameters. Teams can tailor profiles while keeping changes reviewed and consistent.", "Activate a rule in the project profile; test its impact before rollout", "What does a quality profile control?", "Which analyzer rules are active, including rule parameters, for a language and project."),
    ("sonar-rules", "Writing and Tuning Rules", "rules", "intermediate", "Rule tuning should reduce noise without masking real risk. Use a narrow scope, understand the rule's rationale and document exceptions with an owner and review date.", "Prefer a scoped parameter adjustment over a global broad exclusion", "What is a safe way to reduce noisy findings?", "Review representative cases, tune the smallest relevant scope, and preserve coverage of security-sensitive code."),
    ("sonar-issues", "Issue Types and Severity", "rules", "basic", "Findings are classified by their nature and impact, such as bugs, vulnerabilities, security hotspots or maintainability issues. Severity helps prioritize but needs engineering context.", "Bug: likely incorrect behavior · Vulnerability: exploitable weakness · Hotspot: review required", "Are all security hotspots confirmed vulnerabilities?", "No. A hotspot calls for human security review; the reviewer determines whether the code is risky."),
    ("sonar-triage", "Triage, Resolve and Accept Findings", "rules", "intermediate", "Triage confirms whether an issue is valid, fixes it or records a justified disposition. Marking a finding accepted or false positive should preserve a clear explanation and audit trail.", "Assign owner → reproduce context → fix or document a bounded exception", "Why should a false-positive disposition include context?", "It helps future maintainers understand the decision and prevents repeated re-triage."),
    ("sonar-quality-gate", "Quality Gates", "quality", "basic", "A quality gate evaluates analysis against explicit conditions and returns pass or fail. Prefer actionable conditions focused on newly introduced code so older debt does not block every change indefinitely.", "Fail if new-code coverage < 80% or new blocker issues > 0", "What is a quality gate?", "A policy that evaluates analysis metrics and decides whether the project meets its configured quality bar."),
    ("sonar-new-code", "New Code Period and Baselines", "quality", "intermediate", "New-code policy measures changes relative to a selected baseline or period. A stable baseline makes comparisons meaningful across branches and releases.", "Compare a pull request with its target branch", "Why focus gates on new code?", "It encourages teams to stop adding debt while allowing existing issues to be addressed incrementally."),
    ("sonar-coverage", "Coverage Import and Test Reports", "quality", "intermediate", "SonarQube imports test and coverage reports generated by test tools; it does not execute tests by itself. Paths and report formats must match the build workspace.", "Generate coverage report → configure report path → analyze", "Does SonarQube create coverage data?", "Usually no; the test tooling generates it and the scanner imports the report."),
    ("sonar-duplication", "Duplication and Maintainability Metrics", "quality", "intermediate", "Maintainability metrics such as duplication and code smells help identify patterns to review, but they are signals rather than a direct measurement of engineering quality.", "Review a duplicated block and decide whether shared abstraction improves clarity", "Should duplication always be removed?", "No. Abstraction can add coupling; use the metric as a prompt for a contextual design decision."),
    ("sonar-branch", "Branch and Pull Request Analysis", "delivery", "intermediate", "Branch analysis tracks quality on a branch, while pull-request analysis focuses feedback on a proposed change. Correct SCM metadata and branch settings support reliable comparison.", "Analyze PR 142 against main; publish the gate status back to the check", "What should a PR check communicate?", "The analysis result, quality-gate status and actionable new findings."),
    ("sonar-azure", "Azure DevOps Pipeline Integration", "delivery", "intermediate", "A pipeline prepares the build context, runs analysis, waits for the quality gate and publishes a status. Use a scoped service connection and protect secrets.", "Prepare → analyze → publish results → await gate → build or deploy", "Where should a quality gate run in CI?", "After analysis processing completes and before promotion or deployment decisions."),
    ("sonar-github", "GitHub Actions and Pull Request Checks", "delivery", "intermediate", "A CI workflow authenticates to SonarQube with a protected token, runs analysis on the intended revision and exposes the quality result as a check.", "Store SONAR_TOKEN as a protected CI secret", "Why protect analysis tokens?", "A leaked token may allow unauthorized project access or analysis submission; scope and rotate it."),
    ("sonar-secrets", "Secrets and Sensitive Data", "delivery", "advanced", "Scanner credentials belong in secret stores or protected variables, not source files or command logs. Masking is helpful but does not replace least privilege.", "Use a short-lived or narrowly scoped CI credential", "What is the safest place for a scanner token?", "A protected secret store or CI secret variable with minimal permissions and rotation."),
    ("sonar-decorators", "Quality Gate Decoration and Feedback", "delivery", "intermediate", "Pull-request decoration links analysis findings and gate results to the code review. Keep feedback concise and ensure the status corresponds to the correct commit.", "Show new issue locations and pass/fail status on the exact PR commit", "Why tie status to a commit SHA?", "It prevents an old analysis result from appearing to validate newer, unscanned changes."),
    ("sonar-upgrade", "Server, Analyzer and Plugin Upgrades", "delivery", "advanced", "Upgrades can change rules, analyzers and report behavior. Review compatibility, back up supported data and test representative projects before rolling the change out broadly.", "Test upgrade against a representative project set and compare new findings", "What should be checked after an analyzer upgrade?", "Compatibility, changed findings, scanner behavior and gate outcomes on representative code."),
    ("sonar-dashboards", "Dashboards and Quality Trends", "quality", "basic", "Dashboards summarize issue counts, coverage and gate history. Interpret trends with the team's baseline and delivery context instead of optimizing a single metric.", "Track new critical issues and gate pass rate over releases", "Why should teams avoid optimizing one metric alone?", "A single metric can be gamed or improve while reliability, security or delivery outcomes worsen."),
    ("sonar-troubleshoot", "Troubleshoot Missing Analysis Results", "delivery", "intermediate", "When results are missing, verify the scanner ran on the intended source, report submission succeeded, project key and branch are correct, and server processing completed.", "Check scanner logs → confirm project key → inspect background task status", "What should you check first when a dashboard is stale?", "Confirm report submission and processing, then check project and branch identity and the scanner's source scope."),
], "SON", ANALOGY)
